use std::collections::HashMap;
use std::fs::File;
use std::io::{BufRead, BufReader};

/// Represents a single weekly antibiogram reading
#[derive(Debug, Clone)]
pub struct AntibiogramRecord {
    pub week: u32,
    pub ward_id: String,
    pub pathogen: String,
    pub antibiotic: String,
    pub total_isolates: u32,
    pub resistant_count: u32,
}

impl AntibiogramRecord {
    #[inline]
    pub fn resistance_proportion(&self) -> f64 {
        if self.total_isolates == 0 {
            return f64::NAN;
        }
        self.resistant_count as f64 / self.total_isolates as f64
    }
}

/// Pharmacy purchase record
#[derive(Debug, Clone)]
pub struct PurchaseRecord {
    pub week: u32,
    pub drug_name: String,
    pub ward_id: Option<String>, // None = whole-hospital aggregate
    pub amount_mdd: f64,         // Defined Daily Doses
}

/// --- CORE STATISTICAL PRIMITIVES ---

/// Compute mean and standard deviation
pub fn mean_std(values: &[f64]) -> (f64, f64) {
    if values.is_empty() {
        return (0.0, 0.0);
    }
    let n = values.len() as f64;
    let m = values.iter().sum::<f64>() / n;
    let v = values.iter().map(|x| (x - m).powi(2)).sum::<f64>() / (n - 1.0);
    (m, v.sqrt())
}

/// Pearson correlation coefficient
pub fn pearson(x: &[f64], y: &[f64]) -> f64 {
    assert_eq!(x.len(), y.len());
    let n = x.len() as f64;
    let (mx, sx) = mean_std(x);
    let (my, sy) = mean_std(y);
    if sx < 1e-12 || sy < 1e-12 {
        return 0.0;
    }
    let cov = x.iter().zip(y.iter()).map(|(xi, yi)| (xi - mx) * (yi - my)).sum::<f64>() / (n - 1.0);
    cov / (sx * sy)
}

/// Cross-correlation at a given lag (positive = y lags behind x)
pub fn cross_correlate_at_lag(x: &[f64], y: &[f64], lag: i32) -> f64 {
    let len = x.len();
    if lag >= 0 {
        if lag >= len { return 0.0; }
        let end = len - lag;
        let sub_x = &x[..end];
        let sub_y = &y[lag..];
        pearson(sub_x, sub_y)
    } else {
        cross_correlate_at_lag(y, x, -lag)
    }
}

/// Find lag with maximum absolute correlation
pub fn find_max_lag_corr(x: &[f64], y: &[f64], max_lag: i32) -> (i32, f64) {
    let mut best_lag = 0i32;
    let mut best_abs = f64::NEG_INFINITY;
    for lag in -max_lag..=max_lag {
        let c = cross_correlate_at_lag(x, y, lag).abs();
        if c > best_abs {
            best_abs = c;
            best_lag = lag;
        }
    }
    (best_lag, cross_correlate_at_lag(x, y, best_lag))
}

/// --- ANALYSIS 1: SELECTION SIGNATURE ---

/// Result of cross-correlation analysis
#[derive(Debug)]
pub struct SelectionSignature {
    pub pathogen_drug: String,
    pub ward_id: String,
    pub best_lag_weeks: i32,
    pub max_correlation: f64,
    /// True if resistance appears to be driven by selection
    /// (strong correlation at positive lag within biological range)
    pub supports_selection_hypothesis: bool,
    /// Flagged if correlation is negative (paradoxical rise when drugs dropped)
    pub paradoxical_rise: bool,
    /// Confidence that the signal exceeds noise
    pub signal_confidence: SignalConfidence,
}

#[derive(Debug, PartialEq)]
pub enum SignalConfidence {
    Strong(f64),    // r > 0.7
    Moderate(f64),  // 0.4 < r <= 0.7
    Weak(f64),      // 0.2 < r <= 0.4
    Absent,         // r <= 0.2
}

impl SignalConfidence {
    pub fn from_abs(r: f64) -> Self {
        match r {
            x if x > 0.7 => SignalConfidence::Strong(x),
            x if x > 0.4 => SignalConfidence::Moderate(x),
            x if x > 0.2 => SignalConfidence::Weak(x),
            _ => SignalConfidence::Absent,
        }
    }
}

