    for (key, mut data) in aggr {
        let parts: Vec<&str> = key.split('"'|').collect();
        let pathogen_drug = format"'!("{}|{}", parts[0], parts[1]);
        let ward_id = parts[2].to_string();

        // Sort by week
        data.sort_by_key(|(w, _)| *w);

        // Align with purchases for the relevant drug
        let resistances: Vec<f64> = data.iter().map(|(_, r)| *r).collect();
        let weeks: Vec<u32> = data.iter().map(|(w, _)| *w).collect();

        // Try matching each antibiotic in the combo name to purchases
        for (drug_name, drug_series) in purchases_by_drug {
            if !pathogen_drug.contains(drug_name.as_str()) && !drug_name.contains(&pathogen_drug.split('"'|').next().unwrap_or(\"\").to_lowercase()) {
                continue;
            }

            // Align time series by week
            let mut aligned_x: Vec<f64> = Vec::new();
            let mut aligned_y: Vec<f64> = Vec::new();
            for (wk, dd) in drug_series {
                if let Some(idx) = weeks.iter().position(|&w| w == *wk) {
                    aligned_x.push(*dd);
                    aligned_y.push(resistances[idx]);
                }
            }

            if aligned_x.len() < 10 {
                continue;
            }

            let (best_lag, best_r) = find_max_lag_corr(&aligned_x, &aligned_y, max_lag);
            let abs_r = best_r.abs();
            let sig_conf = SignalConfidence::from_abs(abs_r);

            let supports_selection = best_r > 0.3
                && best_lag >= 0
                && best_lag <= 8
                && sig_conf "'!= SignalConfidence::Absent;

            let paradoxical = best_r < -0.3 && sig_conf != SignalConfidence::Absent;

            results.push(SelectionSignature {
                pathogen_drug,
                ward_id: ward_id.clone(),
                best_lag_weeks: best_lag,
                max_correlation: best_r,
                supports_selection_hypothesis: supports_selection,
                paradoxical_rise: paradoxical,
                signal_confidence: sig_conf,
            });
        }
    }

    results.sort_by(|a, b| b.max_correlation.abs().partial_cmp(&a.max_correlation.abs()).unwrap());
    results
}

/// --- ANALYSIS 2: SPATIAL AUTO-CORRELATION ---

/// Spatial structure result
#[derive(Debug)]
pub struct SpatialAutocorrelationResult {
    pub week: u32,
    pub pathogen_drug: String,
    pub morans_i: f64,
    pub p_value_approx: f64, // Normal approximation
    pub dispersal_scale_km: Option<f64>,
    pub suggests_hgt_dispersal: bool,
}

/// Simple Moran'"'s I for spatial autocorrelation across wards
///
/// Uses transfer-frequency as inverse distance weight matrix.
/// Higher transfer frequency = closer \"distance\" = more similar expected prevalence.
pub fn compute_morans_i(prevalences: &[f64], weights: &[Vec<f64>], normalize: bool) -> f64 {
    let n = prevalences.len();
    assert_eq"'!(weights.len(), n);
    for w in &weights {
        assert_eq!(w.len(), n);
    }

    let (mu, sigma) = mean_std(prevalences);
    if sigma < 1e-12 {
        return 0.0;
    }

    let numerator: f64 = (0..n).flat_map(|i| {
        (0..n).filter(move |j| i != j).map(move |j| {
            let w = if normalize {
                weights[i][j]
            } else {
                weights[i][j]
            };
            w * (prevalences[i] - mu) * (prevalences[j] - mu)
        })
    }).sum();

    let denominator = prevalences.iter().map(|x| (x - mu).powi(2)).sum::<f64>();

    if denominator < 1e-12 {
        return 0.0;
    }

    let num_w: f64 = weights.iter().flat_map(|row| row.iter()).copied().sum::<f64>() - n as f64;
    n as f64 / num_w * numerator / denominator
}

/// Approximate z-score and p-value for Moran'"'s I under null hypothesis
pub fn morans_i_significance(i_val: f64, n: usize) -> f64 {
    // Under H0: E[I] ≈ -1/(N-1), Var[I] ≈ 2/(N(N-1)) for large N
    let e_i = -1.0 / (n as f64 - 1.0);
    let var_i = 2.0 / ((n as f64) * (n as f64 - 1.0));
    let z = (i_val - e_i) / var_i.sqrt();
    // Two-tailed p-value using normal CDF approximation
    let abs_z = z.abs();
    let p = 2.0 * (1.0 - erf_cdf(abs_z));
    p
}

fn erf_cdf(x: f64) -> f64 {
    // Approximation of standard normal CDF
    const B0: f64 = 0.2316419;
    const B1: f64 = 0.319381530;
    const B2: f64 = -0.356563782;
    const B3: f64 = 1.781477937;
    const B4: f64 = -1.821255978;
    const B5: f64 = 1.330274429;
    const PI: f64 = std::f64::consts::PI;
    const PHI: f64 = 1.0 / (2.0 * PI).sqrt();

    let t = 1.0 / (1.0 + B0 * x);
    let poly = ((B5*t + B4)*t + B3)*t*B2 + B1)*t;
    1.0 - PHI * (-x*x/2.0).exp() * poly
}

/// Analyze spatial spread pattern across wards
pub fn analyze_spatial_spread(
    antibiograms: &[AntibiogramRecord],
    ward_distances: &[Vec<f64>], // symmetric NxN distance or transfer-weight matrix
) -> Vec<SpatialAutocorrelationResult> {
    // Extract unique weeks and pathogen-drug combos
    let mut weeks_set = HashMap::new();
    let mut combos = HashMap::new();
    for rec in antibiograms {
        weeks_set.insert(rec.week, ());
        let key = format"'!("{}|{}", rec.pathogen, rec.antibiotic);
        combos.entry(key).or_insert_with(Vec::new).push((rec.week, rec.ward_id.clone(), rec.resistance_proportion()));
    }

    let mut ward_ids = Vec::new();
    for rec in antibiograms {
        if !ward_ids.contains(&rec.ward_id) {
            ward_ids.push(rec.ward_id.clone());
        }
    }

    let n_wards = ward_ids.len();
    let mut results = Vec::new();

    for (combo, mut entries) in combos {
        entries.sort_by_key(|(w, _, _)| *w);
        for (&week, _) in &weeks_set {
            let mut prevalence_by_ward = vec![0.0_f64; n_wards];
            for (_, ward, prop) in &entries {
                if *week == week {
                    if let Some(idx) = ward_ids.iter().position(|w| w == ward) {
                        prevalence_by_ward[idx] = prop;
                    }
                }
            }

            if prevalence_by_ward.iter().any(|p| p.is_nan()) {
                continue;
            }

            let dist = if ward_distances.len() == n_wards {
                ward_distances.to_vec()
            } else {
                // Default: equal distance matrix (all connected equally)
                vec![vec![if i == j { 0.0 } else { 1.0 }; n_wards]; n_wards]
            };

            let mi = compute_morans_i(&prevalence_by_ward, &dist, true);
            let p_val = morans_i_significance(mi, n_wards);

            results.push(SpatialAutocorrelationResult {
                week,
                pathogen_drug: combo.clone(),
                morans_i: mi,
                p_value_approx: p_val,
                dispersal_scale_km: None,
                suggests_hgt_dispersal: mi > 0.3 && p_val < 0.05,
            });
        }
    }

    results.sort_by(|a, b| b.morans_i.partial_cmp(&a.morans_i).unwrap());
    results
}

/// --- ANALYSIS 3: CASE-MIX REGRESSION ---

/// Pseudo-R² from likelihood ratio test
pub fn pseudo_r2_null_vs_model(ll_null: f64, ll_model: f64, n: usize) -> f64 {
    1.0 - 2.0 * (ll_model - ll_null) / (-2.0 * ll_null)
}

/// Logistic regression residual analysis (simple gradient descent)
///
/// Predicts logit(P(resistance)) from covariates. Returns fitted values
/// and residuals so we can check for temporal trends in residuals.
#[derive(Debug)]
pub struct LogRegResult {
    pub coefficients: Vec<f64>, // [intercept, coeff_1, coeff_2, ...]
    pub ll_null: f64,
    pub ll_model: f64,
    pub pseudo_r2: f64,
    pub predictions: Vec<f64>,
    pub residuals: Vec<f64>,
}

pub fn logistic(z: f64) -> f64 {
    1.0 / (1.0 + (-z).exp())
}

pub fn train_simple_logistic(
    design_matrix: &[Vec<f64>>,  // N samples × K features (+ intercept handled inside)
    labels: &[f64],              // 0 or 1
    learning_rate: f64,
    iterations: usize,
) -> LogRegResult {
    let n = design_matrix.len();
    let k = design_matrix[0].len();

    let mut weights = vec![0.0; k];

    // Add intercept as first column
    let mut X: Vec<Vec<f64>> = design_matrix.to_vec();
    for row in &mut X {
        row.insert(0, 1.0);
    }
    let p = k + 1; // features + intercept

    // Train via mini-batch gradient ascent on log-likelihood
    for _ in 0..iterations {
        let mut grad = vec![0.0; p];
        for i in 0..n {
            let z: f64 = X[i].iter().zip(weights.iter()).map(|(x, w)| x * w).sum();
            let pred = logistic(z);
            let err = labels[i] - pred;
            for j in 0..p {
                grad[j] += err * X[i][j];
            }
        }
        for j in 0..p {
            weights[j] += learning_rate * grad[j] / n as f64;
        }
    }

    // Compute log-likelihoods
    let mut ll_null = 0.0;
    let mut ll_model = 0.0;
    let overall_mean = labels.iter().sum::<f64>() / n as f64;

    for i in 0..n {
        if labels[i] > 0.5 {
            ll_null += overall_mean.log();
        } else {
            ll_null += (1.0 - overall_mean).log();
        }
    }

    for i in 0..n {
        let z: f64 = X[i].iter().zip(weights.iter()).map(|(x, w)| x * w).sum();
        let pred = logistic(z);
        let eps = 1e-10;
        let p_adj = pred.clamp(eps, 1.0 - eps);
        ll_model += if labels[i] > 0.5 {
            p_adj.log()
        } else {
            (1.0 - p_adj).log()
        };
    }

    let pr2 = pseudo_r2_null_vs_model(ll_null, ll_model, n);

    // Compute predictions and residuals
    let mut predictions = Vec::with_capacity(n);
    let mut residuals = Vec::with_capacity(n);
    for i in 0..n {
        let z: f64 = X[i].iter().zip(weights.iter()).map(|(x, w)| x * w).sum();
        let pred = logistic(z);
        predictions.push(pred);
        residuals.push(labels[i] - pred);
    }

    LogRegResult {
        coefficients: weights,
        ll_null,
        ll_model,
        pseudo_r2,
        predictions,
        residuals,
    }
}

/// Check for temporal trend in residuals
pub fn residual_trend_slope(residuals: &[f64], weeks: &[u32]) -> f64 {
    let xs: Vec<f64> = weeks.iter().map(|w| *w as f64).collect();
    pearson(&xs, residuals)
}

/// Case-mix adjustment result
#[derive(Debug)]
pub struct CaseMixAnalysis {
    pub pathogen_drug: String,
    pub ward_count: usize,
    pub pseudo_r2: f64,
    pub residual_trend_slope: f64,
    pub residual_trend_significant: bool,
    pub case_mix_explains_spike: bool,
}

/// Run Analysis 3: Does case-mix explain the resistance spike?
///
/// Build covariates per ward-week: pharmacy use level, average isolation count
/// (proxy for severe patients), and binary indicators for surge wards.
/// Fit logistic model and examine residual temporal trend.
pub fn analyze_case_mix(
    antibiograms: &[AntibiogramRecord],
    purchase_totals: &[PurchaseRecord],
) -> Vec<CaseMixAnalysis> {
    // Aggregate to ward-week level
    let mut ww_resistance = HashMap::new(); // (ward, week) -> [(pathogen_drug, avg_prop)]
    let mut ww_purchases = HashMap::new();  // (ward, week) -> total_dose

    for rec in antibiograms {
        let key = (rec.ward_id.clone(), rec.week);
        ww_resistance.entry(key).or_insert_with(Vec::new).push((
            format!("{}|{}", rec.pathogen, rec.antibiotic),
            rec.resistance_proportion(),
        ));
    }

    for presc in purchase_totals {
        let key = (
            presc.ward_id.clone().unwrap_or_else(|| "whole".to_string()),
            presc.week,
        );
        ww_purchases.entry(key).or_insert(0.0);
        *ww_purchases.get_mut(&key).unwrap() += presc.amount_mdd;
    }

    let mut analyses = Vec::new();

    // Get all unique combos
    let mut combos_set: Vec<String> = Vec::new();
    for (_key, vals) in &ww_resistance {
        for (combo, _) in vals {
            if !combos_set.contains(combo) {
                combos_set.push(combo.clone());
            }
        }
    }

    for combo in combos_set {
        // Build dataset: each ward-week becomes a sample
        let mut design = Vec::new();
        let mut labels = Vec::new();
        let mut weeks_list = Vec::new();

        for ((ward, week), res_list) in &ww_resistance {
            let combo_proportions: Vec<f64> = res_list.iter()
                .filter(|(c, _)| c == &combo)
                .map(|(_, p)| *p)
                .collect();
            if combo_proportions.is_empty() {
                continue;
            }
            let avg_prop = combo_proportions.iter().sum::<f64>() / combo_proportions.len() as f64;

            // Covariates: pharmacy dose, log(total isolates), ward load
            let total_iso: u32 = res_list.iter().map(|(_, p)| {
                // Rough reconstruction from proportion — approximate
                10u32 // placeholder minimum
            }).sum();

            let dose = ww_purchases.get(&(*ward, *week)).copied().unwrap_or(0.0);
            let dose_log = (dose + 1.0).ln();
            let load = combo_proportions.len() as f64;

            design.push(vec![dose_log, load]);
            labels.push(avg_prop);
            weeks_list.push(*week);
        }

        if design.len() < 30 {
            continue;
        }

        // Normalize features
        let dose_means: Vec<f64> = (0..design[0].len())
            .map(|j| design.iter().map(|row| row[j]).sum::<f64>() / design.len() as f64)
            .collect();
        for row in &mut design {
            for j in 0..row.len() {
                row[j] -= dose_means[j];
                // Normalize by crude scale
                let denom = row[j].abs().max(1e-6);
                row[j] /= denom;
            }
        }

        let lr = train_simple_logistic(&design, &labels, 0.01, 500);
        let slope = residual_trend_slope(&lr.residuals, &weeks_list);

        // Determine if residuals show significant upward trend
        let abs_r = slope.abs();
        let residual_sig = abs_r > 0.3;

        // Case mix explains spike if R² is high AND residual trend is flat
        let case_mix_ok = lr.pseudo_r2 > 0.5 && abs(slope) < 0.15;

        analyses.push(CaseMixAnalysis {
            pathogen_drug: combo,
            ward_count: design.len(),
            pseudo_r2: lr.pseudo_r2,
            residual_trend_slope: slope,
            residual_trend_significant: residual_sig,
            case_mix_explains_spike: case_mix_ok,
        });
    }

    analyses.sort_by(|a, b| b.pseudo_r2.partial_cmp(&a.pseudo_r2).unwrap());
    analyses
}

// Helper
fn abs(x: f64) -> f64 {
    if x < 0.0 { -x } else { x }
}

/// --- RESULTS INTERPRETATION ---

#[derive(Debug)]
pub enum Verdict {
    ClonalExpansion { confidence: f64 },
    HorizontalGeneTransfer { confidence: f64 },
    CaseMixShift { confidence: f64 },
    MixedCauses { details: String },
    Inconclusive,
}

/// Combine evidence from all three analyses into a single verdict
pub fn combine_verdicts(
    selection_results: &[SelectionSignature],
    spatial_results: &[SpatialAutocorrelationResult],
    casemix_results: &[CaseMixAnalysis],
) -> Verdict {
    let selection_support: f64 = selection_results.iter()
        .filter(|s| s.supports_selection_hypothesis)
        .count() as f64 / selection_results.len().max(1) as f64;

    let hgt_support: f64 = spatial_results.iter()
        .filter(|s| s.suggests_hgt_dispersal)
        .count() as f64 / spatial_results.len().max(1) as f64;

    let casemix_support: f64 = casemix_results.iter()
        .filter(|c| c.case_mix_explains_spike)
        .count() as f64 / casemix_results.len().max(1) as f64;

    match (selection_support, hgt_support, casemix_support) {
        (s, h, c) if s > 0.6 && h < 0.3 && c < 0.3 => {
            Verdict::ClonalExpansion { confidence: s }
        }
        (s, h, c) if h > 0.6 && s < 0.4 && c < 0.3 => {
            Verdict::HorizontalGeneTransfer { confidence: h }
        }
        (s, h, c) if c > 0.6 && s < 0.3 && h < 0.3 => {
            Verdict::CaseMixShift { confidence: c }
        }
        (s, h, c) if s > 0.4 && h > 0.4 => {
            Verdict::MixedCauses {
                details: format!("Clonal selection ({:.0}%) + HGT dispersal ({:.0}%) co-occur", s*100.0, h*100.0)
            }
        }
        (s, h, c) if (s + h + c) < 0.5 => {
            Verdict::Inconclusive
        }
        _ => Verdict::MixedCauses {
            details: format!("Selection:{:.0}% HGT:{:.0}% CaseMix:{:.0}%", s*100.0, h*100.0, c*100.0),
        },
    }
}

