#[derive(Debug, Clone)]
pub struct AntibiogramRecord {
    pub week: u32,
    pub ward_id: String,
    pub pathogen: String,
    pub antibiotic: String,
    pub total_isolates: u32,
    pub resistant_count: u32,
}

impl AntibiogramRecord {
    pub fn resistance_proportion(&self) -> f64 {
        if self.total_isolates == 0 {
            return f64::NAN;
        }
        self.resistant_count as f64 / self.total_isolates as f64
    }
}

