// --- STATISTICAL PRIMITIVES ---

pub fn mean_std(values: &[f64]) -> (f64, f64) {
    let n = values.len() as f64;
    if n < 2.0 {
        return (0.0, 0.0);
    }
    let m = values.iter().sum::<f64>() / n;
    let v = values.iter().map(|x| (x - m).powi(2)).sum::<f64>() / (n - 1.0);
    (m, v.sqrt())
}

pub fn pearson(x: &[f64], y: &[f64]) -> f64 {
    assert_eq!(x.len(), y.len());
    let n = x.len() as f64;
    let (mx, sx) = mean_std(x);
    let (my, sy) = mean_std(y);
    if sx < 1e-12 || sy < 1e-12 {
        return 0.0;
    }
    let cov = x.iter().zip(y.iter()).map(|(xi, yi)| (xi - mx) * (yi - my)).sum::<f64>() / (n - 1.0);
    cov / (sx * sy)
}

pub fn cross_correlate_at_lag(x: &[f64], y: &[f64], lag: i32) -> f64 {
    if lag >= 0 && lag < x.len() as i32 {
        let end = x.len() - lag as usize;
        pearson(&x[..end], &y[lag..])
    } else if lag <= 0 && -lag < y.len() as i32 {
        let al = -lag;
        pearson(&y[..(y.len() - al as usize)], &x[al..])
    } else {
        0.0
    }
}

pub fn find_max_lag_corr(x: &[f64], y: &[f64], max_lag: i32) -> (i32, f64) {
    let mut best_lag = 0i32;
    let mut best_abs = f64::NEG_INFINITY;
    for lag in -max_lag..=max_lag {
        let c = cross_correlate_at_lag(x, y, lag).abs();
        if c > best_abs {
            best_abs = c;
            best_lag = lag;
        }
    }
    (best_lag, cross_correlate_at_lag(x, y, best_lag))
}

