}

impl SignalConfidence {
    pub fn from_abs(r: f64) -> Self {
        match r {
            r if r > 0.7 => SignalConfidence::Strong(r),
            r if r > 0.4 => SignalConfidence::Moderate(r),
            r if r > 0.2 => SignalConfidence::Weak(r),
            _ => SignalConfidence::Absent,
        }
    }
}

pub fn analyze_selection_signatures(
    purchases_by_drug: &HashMap<String, Vec<(u32, f64)>>,
    antibiograms: &[AntibiogramRecord],
    max_lag: i32,
) -> Vec<SelectionSignature> {
    let mut aggr = HashMap::new();
    for rec in antibiograms {
        let key = format!("{}|{}|{}", rec.pathogen, rec.antibiotic, rec.ward_id);
        aggr.entry(key).or_insert_with(Vec::new).push((rec.week, rec.resistance_proportion()));
    }

    let mut results = Vec::new();
    for (key, mut data) in aggr {
        let parts: Vec<&str> = key.split('"'|').collect();
        if parts.len() "'!= 3 { continue; }
        let pathogen_drug = format!("{}|{}", parts[0], parts[1]);
        let ward_id = parts[2].to_string();

        data.sort_by_key(|(w, _)| *w);
        let resistances: Vec<f64> = data.iter().map(|(_, r)| *r).collect();
        let weeks: Vec<u32> = data.iter().map(|(w, _)| *w).collect();

        // Try matching each antibiotic name
        let abx_names: Vec<&str> = parts[1].split('"',').collect();
        for drug_name in &abx_names {
            for (purchase_drug, drug_series) in purchases_by_drug {
                let lower_pd = purchase_drug.to_lowercase();
                let lower_antd = drug_name.to_lowercase();
                if lower_pd.contains(&lower_antd) || lower_antd.contains(&lower_pd) {
                    let mut aligned_x: Vec<f64> = Vec::new();
                    let mut aligned_y: Vec<f64> = Vec::new();
                    for (wk, dd) in drug_series {
                        if let Some(idx) = weeks.iter().position(|&w| w == *wk) {
                            aligned_x.push(*dd);
                            aligned_y.push(resistances[idx]);
                        }
                    }
                    if aligned_x.len() < 10 { continue; }
                    let (best_lag, best_r) = find_max_lag_corr(&aligned_x, &aligned_y, max_lag);
                    let abs_r = best_r.abs();
                    let sig = SignalConfidence::from_abs(abs_r);
                    let supports = best_r > 0.3 && best_lag >= 0 && best_lag <= 8 && sig "'!= SignalConfidence::Absent;
                    let paradoxical = best_r < -0.3 && sig != SignalConfidence::Absent;
                    results.push(SelectionSignature {
                        pathogen_drug: pathogen_drug.clone(),
                        ward_id: ward_id.clone(),
                        best_lag_weeks: best_lag,
                        max_correlation: best_r,
                        supports_selection_hypothesis: supports,
                        paradoxical_rise: paradoxical,
                        signal_confidence: sig,
                    });
                }
            }
        }
    }
    results.sort_by(|a, b| b.max_correlation.abs().partial_cmp(&a.max_correlation.abs()).unwrap());
    results
}

