#[derive(Debug)]
pub struct SpatialAutocorrelationResult {
    pub week: u32,
    pub pathogen_drug: String,
    pub morans_i: f64,
    pub p_value_approx: f64,
    pub suggests_hgt_dispersal: bool,
}

pub fn compute_morans_i(prevalences: &[f64], weights: &[Vec<f64>], _normalize: bool) -> f64 {
    let n = prevalences.len();
    let mu = prevalences.iter().sum::<f64>() / n as f64;
    let sigma_sq = prevalences.iter().map(|x| (x - mu).powi(2)).sum::<f64>();
    if sigma_sq < 1e-12 { return 0.0; }

    let mut numerator = 0.0_f64;
    for i in 0..n {
        for j in 0..n {
            if i != j {
                numerator += weights[i][j] * (prevalences[i] - mu) * (prevalences[j] - mu);
            }
        }
    }

    let mut sum_w = 0.0_f64;
    for row in weights {
        for &w in row { sum_w += w; }
    }

    (n as f64 / sum_w) * numerator / sigma_sq
}

fn normal_cdf_positive(z: f64) -> f64 {
    // Abramowitz and Stegun approximation
    let a1 = 0.254829593f64;
    let a2 = -0.284496736f64;
    let a3 = 1.421413741f64;
    let a4 = -1.453152027f64;
    let a5 = 1.061405429f64;
    let p = 0.3275911f64;
    let sign = if z < 0.0 { -1.0 } else { 1.0 };
    let az = z.abs();
    let t = 1.0 / (1.0 + p * az);
    let y = 1.0 - (((((a5*t + a4)*t) + a3)*t + a2)*t + a1)*t * (-az*az/2.0).exp();
    0.5 * (1.0 + sign * y)
}

pub fn morans_i_significance(i_val: f64, n: usize) -> f64 {
    let e_i = -1.0 / (n as f64 - 1.0);
    let var_i = 2.0 / ((n as f64) * (n as f64 - 1.0));
    let z = (i_val - e_i) / var_i.sqrt();
    let two_tailed_p = 2.0 * (1.0 - normal_cdf_positive(z.abs()));
    two_tailed_p
}

pub fn analyze_spatial_spread(antibiograms: &[AntibiogramRecord], ward_distances: &[Vec<f64>]) -> Vec<SpatialAutocorrelationResult> {
    let mut weeks_set = Vec::new();
    let mut combos_map: HashMap<String, Vec<(u32, String, f64)>> = HashMap::new();

    for rec in antibiograms {
        let prop = rec.resistance_proportion();
        combos_map.entry(format!("{}|{}", rec.pathogen, rec.antibiotic))
                  .or_insert_with(Vec::new)
                  .push((rec.week, rec.ward_id.clone(), prop));
        if !weeks_set.contains(&rec.week) {
            weeks_set.push(rec.week);
        }
    }

    let mut ward_ids = Vec::new();
    for rec in antibiograms {
        if !ward_ids.contains(&rec.ward_id) {
            ward_ids.push(rec.ward_id.clone());
        }
    }

    let n_wards = ward_ids.len();
    let mut results = Vec::new();

    let default_dist: Vec<Vec<f64>> = (0..n_wards).map(|i| {
        (0..n_wards).map(|j| if i == j { 0.0 } else { 1.0 }).collect()
    }).collect();

    let dist = if ward_distances.len() == n_wards { ward_distances } else { &default_dist };

    for (combo, mut entries) in combos_map {
        entries.sort_by_key(|(w, _, _)| *w);
        for &week in &weeks_set {
            let mut prev_by_ward = vec![0.0_f64; n_wards];
            for (&ew, ward, prop) in &entries {
                if ew == week {
                    if let Some(idx) = ward_ids.iter().position(|w| w == ward) {
                        prev_by_ward[idx] = prop;
                    }
                }
            }

            if prev_by_ward.iter().any(|p| p.is_nan()) { continue; }

            let mi = compute_morans_i(&prev_by_ward, dist, true);
            let p_val = morans_i_significance(mi, n_wards);

            results.push(SpatialAutocorrelationResult {
                week,
                pathogen_drug: combo.clone(),
                morans_i: mi,
                p_value_approx: p_val,
                suggests_hgt_dispersal: mi > 0.3 && p_val < 0.05,
            });
        }
    }

    results.sort_by(|a, b| b.morans_i.partial_cmp(&a.morans_i).unwrap());
    results
}

